1/(k-1)! Sum[((i+\[Lambda])^(k-1) \[Theta]^-1 qq^(i+\[Lambda]))/(1-\[Theta]^-1 qq^(i+\[Lambda])),{i,0,2order}]
]
+(-1)^k/(k-1)! Sum[((i-\[Lambda])^(k-1) \[Theta] qq^(i-\[Lambda]))/(1-\[Theta] qq^(i-\[Lambda])),{i,1,2order}])//PowerExpand//Series[#,{q,0,order}]&//Simplify
