result=Exp[\[Pi] I((l+(-m))/(12p)-DedekindSum[-m,p])]Sqrt[-I(p u+(-m))]\[Eta]\[Eta][E^(2\[Pi] I u)]/.u->(m+\[Tau])/p,
None
