If[l==0&&p>1,result=Sqrt[-I p \[Tau]]\[Eta]\[Eta][E^(2\[Pi] I p \[Tau])]];
If[l==0&&p==1,result=Sqrt[-I \[Tau]/-numerator]\[Eta]\[Eta][E^(2\[Pi] I  \[Tau]/-numerator)]];

result
];



